import "server-only";
import { randomUUID } from "node:crypto";
import { after } from "next/server";
import { checkRateLimit, hasDistributedRateLimit } from "../ops/rate-limit";
import { resourceContext } from "./resource-context";

const SITE = "fb45af18-7b52-42ac-bf1c-19523ae7ab8f";
const URL = `https://visitorping.com/api/agent-integrations/${SITE}/resources`;
const MAX_BYTES = 262144;
let nextSampleAt = 0;

/** Body bytes generated by this origin, not compressed network transfer or CDN billing. */
export async function boundedResponseBytes(response: Response): Promise<number | undefined> {
  if (!response.headers.get("content-type")?.includes("application/json") || !response.body) return undefined;
  const reader = response.clone().body!.getReader();
  let size = 0;
  let timer: ReturnType<typeof setTimeout> | undefined;
  try {
    return await Promise.race([
      (async () => {
        while (true) {
          const { done, value } = await reader.read();
          if (done) return size;
          size += value.byteLength;
          if (size > MAX_BYTES) return undefined;
        }
      })(),
      new Promise<undefined>(resolve => { timer = setTimeout(() => resolve(undefined), 1000); }),
    ]);
  } finally {
    clearTimeout(timer);
    // A tee branch's cancellation can wait for the other branch: do not await it.
    void reader.cancel().catch(() => {});
  }
}

/** Samples successful origin API responses; never extrapolates to all traffic or AI traffic. */
export async function observeResources(handler: () => Promise<Response>): Promise<Response> {
  const token = process.env.VISITORPING_RESOURCE_MERCHANT_TOKEN;
  if (process.env.VERCEL_ENV !== "production" ||
      process.env.VISITORPING_RESOURCE_REPORTING_ENABLED !== "true" ||
      !/^vp_agent_[A-Za-z0-9_-]{43}$/.test(token ?? "") ||
      !hasDistributedRateLimit() || Date.now() < nextSampleAt) return handler();
  // Per-process suppression reduces overhead. The shared budget below is authoritative.
  nextSampleAt = Date.now() + 60000;
  const counters = { reads: 0, writes: 0, unknown: false };
  const response = await resourceContext.run(counters, handler);
  if (response.status !== 200) return response;
  const units: Record<string, number> = { apiCalls: 1 };
  if (!counters.unknown) {
    units.databaseReads = counters.reads;
    units.databaseWrites = counters.writes;
  }
  // Clone before Next consumes the original response; bound both bytes and read time.
  const measuredBytes = boundedResponseBytes(response).catch(() => undefined);
  const externalId = `limitsregistry_api_${randomUUID()}`;
  try {
    // No request, URL, headers, SQL, user identity, or body content is sent to VisitorPing.
    after(async () => {
      try {
        const budget = await checkRateLimit("visitorping-resources", 900, 86400000);
        if (!budget.allowed) return;
        const bytes = await measuredBytes;
        if (bytes !== undefined) units.bandwidthBytes = bytes;
        const result = await fetch(URL, {
          method: "POST", headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
          body: JSON.stringify({ externalId, units }), redirect: "error", cache: "no-store",
          signal: AbortSignal.timeout(5000),
        });
        if (!result.ok) {
          nextSampleAt = Date.now() + (result.status === 401 ? 3600000 : 300000);
          console.error(`[visitorping-resources] Report rejected (${result.status}); coverage is incomplete.`);
        }
      } catch {
        nextSampleAt = Date.now() + 300000;
        console.error("[visitorping-resources] Reporting unavailable; coverage is incomplete.");
      }
    });
  } catch {
    console.error("[visitorping-resources] Reporting could not be scheduled.");
  }
  return response;
}
